// run_id is threaded forward as a value, never re-derived (D14).
const p   = $input.first().json.output ?? {};
const inp = $('When Executed by Another Workflow').first().json;
const arr = v => Array.isArray(v) ? v.map(s => String(s).trim()).filter(Boolean) : [];

const batch = Number(p.batch_size_l);
return [{ json: {
  run_id:         $('Start run').first().json.run_id,
  question:       String(inp.question ?? ''),
  session_id:     String(inp.session_id ?? '').trim(),
  style:          String(p.style ?? '').trim() || 'beer',
  batch_size_l:   Number.isFinite(batch) && batch > 0 ? Math.min(batch, 1000) : 20,
  target_abv_pct: Number(p.target_abv_pct) > 0 ? Number(p.target_abv_pct) : 0,
  descriptors:    arr(p.descriptors),
  must_include:   arr(p.must_include),
  avoid:          arr(p.avoid),
}}];

const brief = $('Unpack brief').first().json;
const rows  = $('Step 2 · retrieve').first().json.rows ?? [];
const cat   = $input.all().map(i => i.json);

if (!cat.length) throw new Error('brew.f_catalogue returned no ingredients');

const idmap = {};
const passages = rows.map((r, n) => {
  const label = `S${n + 1}`;
  idmap[r.chunk_id] = { label, doc_title: r.doc_title, page: r.page };
  return `[${label}] ${r.doc_title} · ${r.heading}${r.page ? ` · p.${r.page}` : ''}\n${r.text}`;
}).join('\n\n');

// The catalogue is the biggest thing in the prompt, so it carries only the
// columns the model actually chooses on. names[] is kept for `compose`, which
// must print ingredient names it never has to look up itself.
const names = {}, kinds = {}, roles = {};
for (const c of cat) {
  names[c.id] = c.supplier ? `${c.supplier} ${c.name}` : c.name;
  kinds[c.id] = c.kind;
  roles[c.id] = c.role;
}

// Grouped by role, not one flat list. role comes from brew.f_catalogue, derived
// in SQL from published colour -- so "Bohemian Dark Malt" at 6.5 L sits under
// BASE and cannot be picked as a roast malt because of what it is called.
const SECTIONS = [
  ['base',    'BASE MALTS - id | name | ppg | degL'],
  ['caramel', 'CARAMEL & CRYSTAL MALTS (10-199 degL) - id | name | ppg | degL'],
  ['roast',   'ROAST MALTS (>=200 degL) - THE ONLY MALTS THAT MAKE A BEER DARK - id | name | ppg | degL'],
  ['adjunct', 'SUGARS & ADJUNCTS - id | name | ppg | degL'],
  ['hop',     'HOPS - id | name | alpha %'],
];
const catalogue = SECTIONS.map(([role, heading]) => {
  const rows = cat.filter(c => c.role === role).map(c =>
    role === 'hop'
      ? `${c.id} | ${names[c.id]} | ${c.alpha_acid_pct ?? '-'}`
      : `${c.id} | ${names[c.id]} | ${c.potential_ppg ?? '-'} | ${c.color_lovibond ?? '-'}`);
  return rows.length ? `${heading}\n${rows.join('\n')}` : null;
}).filter(Boolean).join('\n\n');

return [{ json: { ...brief, catalogue, passages, idmap, names, kinds, roles,
                  chunk_ids: rows.map(r => r.chunk_id) } }];

const pack = $('Build propose pack').first().json;
const out  = $input.first().json.output ?? {};

const STAGES = new Set(['mash','boil','whirlpool','dryhop','fermenter','packaging']);
const known   = new Set(Object.keys(pack.names).map(Number));
const catKind = pack.kinds;

// A hallucinated ingredient_id would fail the FK inside f_save_recipe anyway;
// dropping it here means the rest of the recipe still gets built, and the drop
// is reported rather than silently swallowed.
const kept = [], dropped = [], assumed = [];
for (const it of (out.items ?? [])) {
  const id  = Number(it.ingredient_id);
  const qty = Math.round(Number(it.qty_g));
  const stage = String(it.stage ?? 'mash');
  if (!known.has(id))            { dropped.push(`unknown ingredient_id ${it.ingredient_id}`); continue; }
  if (!STAGES.has(stage))        { dropped.push(`${pack.names[id]}: bad stage ${stage}`); continue; }
  if (!Number.isFinite(qty) || qty <= 0) { dropped.push(`${pack.names[id]}: bad qty`); continue; }
  const row = { ingredient_id: id, stage, qty_g: qty };
  const t = Number(it.timing_min);
  if (Number.isFinite(t) && t >= 0) row.timing_min = Math.round(t);
  if (it.notes) row.notes = String(it.notes).slice(0, 120);

  // A boil hop with no stated time computes to IBU 0, because Tinseth's
  // boil-time factor is zero at t=0 -- so 30 g of Fuggles would silently
  // contribute nothing. Hops in the kettle DO bitter; assume a standard 60 min
  // bittering addition and say so, rather than report a bitterness we know is
  // wrong. Measured on run 61, which produced exactly this.
  if (row.timing_min == null && stage === 'boil' && catKind[id] === 'hop') {
    row.timing_min = 60;
    row.notes = (row.notes ? row.notes + ' ' : '') + '(boil time not specified; assumed 60 min)';
    assumed.push(`${pack.names[id]}: no boil time given, assumed 60 min`);
  }
  kept.push(row);
}
if (!kept.length) throw new Error('propose returned no usable items: ' + dropped.join('; '));

const att = Number(out.attenuation);
const mash = Number(out.mash_temp_c);
const gaps = [...(Array.isArray(out.not_available) ? out.not_available : []), ...dropped, ...assumed];

return [{ json: {
  ...pack,
  items:        kept,
  dropped,
  assumed,
  gaps,
  rationale:    String(out.rationale ?? ''),
  mash_temp_c:  Number.isFinite(mash) && mash > 30 && mash < 80 ? Math.round(mash) : 67,
  attenuation:  Number.isFinite(att) && att > 0.4 && att < 0.95 ? att : 0.75,
  // A 30% boil-off allowance; only used to gravity-correct hop utilisation.
  boil_volume_l: Math.round(pack.batch_size_l * 1.3 * 10) / 10,
  recipe_name:  [pack.style, pack.must_include.slice(0, 2).join(' & ')]
                  .filter(Boolean).join(' · ').slice(0, 80),
}}];

const v     = $('Validate proposal').first().json;
const fit   = $('Fit to target').first().json.fit;
const saved = $input.first().json.saved;

// The recipe lines are built from the SAVED items, not the proposed ones: the
// grist was scaled to hit the target, so the proposed grams are stale.
const lines = fit.items.map(it => {
  const t = it.timing_min != null ? `, ${it.timing_min} min` : '';
  const n = it.notes ? ` — ${it.notes}` : '';
  return `${v.names[it.ingredient_id]} · ${it.stage}${t} · ${it.qty_g} g${n}`;
}).join('\n');

const c = saved.computed;
const computed = [
  `OG ${c.og}`, `FG ${c.fg}`, `ABV ${c.abv_pct}%`,
  `IBU ${c.ibu}`, `EBC ${c.ebc}`, `SRM ${c.srm}`,
  `batch ${c.batch_size_l} L`, `mash ${v.mash_temp_c} °C`,
].join(' · ');

const sources = Object.values(v.idmap)
  .map(s => `[${s.label}] ${s.doc_title}${s.page ? `, p.${s.page}` : ''}`).join('\n');

return [{ json: {
  run_id: v.run_id,
  question: v.question,
  recipe: lines,
  computed,
  sources: sources || 'none',
  gaps: v.gaps.length ? v.gaps.join('; ') : 'none',
  recipe_id: saved.recipe_id,
  version: saved.version,
  scale_factor: fit.scale_factor,
  spent: JSON.stringify({ recipe_id: saved.recipe_id, version: saved.version,
                          items: saved.items, scale_factor: fit.scale_factor }),
}}];

// One item, one key — the toolWorkflow node hands the last output to the model.
const c = $('Build compose vars').first().json;
const text = String($('Step 4 · compose').first().json.output ?? '').trim()
             || `${c.recipe}\n\n${c.computed}`;
return [{ json: { response: `${text}\n\n(saved as recipe #${c.recipe_id} v${c.version})` } }];
